 * Type definitions for the Location modality viewer.
 */

/**
 * A single location entry (current or historical).
 */
export interface LocationEntry {
  timestamp: string;
  latitude: number;
  longitude: number;
  address?: string;
  named_location?: string;
  altitude?: number;
  accuracy?: number;
  speed?: number;
  bearing?: number;
  is_current?: boolean;
}

/**
 * Location state from the API.
 */
export interface LocationState {
  modality_type: 'location';
  last_updated: string;
  update_count: number;
  current: {
    latitude?: number;
    longitude?: number;
    address?: string;
    named_location?: string;
    altitude?: number;
    accuracy?: number;
    speed?: number;
    bearing?: number;
  };
  history: LocationEntry[];
}

/**
 * A saved/named location stored in cookies.
 */
export interface SavedLocation {
  id: string;
  name: string;
  latitude: number;
  longitude: number;
  address?: string;
  altitude?: number;
}

/**
 * Request to update location via API.
 */
export interface UpdateLocationRequest {
  latitude: number;
  longitude: number;
  address?: string;
  named_location?: string;
  altitude?: number;
  accuracy?: number;
  speed?: number;
  bearing?: number;
}

/**
 * History filter options.
 */
export interface HistoryFilter {
  namedOnly: boolean;
  limit: number;
  sortOrder: 'asc' | 'desc';
}

/**
 * Preset city locations for quick testing.
 */
export interface PresetCity {
  name: string;
  latitude: number;
  longitude: number;
  country: string;
}

/**
 * Common preset cities for testing.
 */
export const PRESET_CITIES: PresetCity[] = [
  { name: 'New York', latitude: 40.7128, longitude: -74.0060, country: 'USA' },
  { name: 'San Francisco', latitude: 37.7749, longitude: -122.4194, country: 'USA' },
  { name: 'Los Angeles', latitude: 34.0522, longitude: -118.2437, country: 'USA' },
  { name: 'Chicago', latitude: 41.8781, longitude: -87.6298, country: 'USA' },
  { name: 'London', latitude: 51.5074, longitude: -0.1278, country: 'UK' },
  { name: 'Paris', latitude: 48.8566, longitude: 2.3522, country: 'France' },
  { name: 'Tokyo', latitude: 35.6762, longitude: 139.6503, country: 'Japan' },
  { name: 'Sydney', latitude: -33.8688, longitude: 151.2093, country: 'Australia' },
  { name: 'Berlin', latitude: 52.5200, longitude: 13.4050, country: 'Germany' },
  { name: 'Toronto', latitude: 43.6532, longitude: -79.3832, country: 'Canada' },
];

/**
 * Convert bearing degrees to compass direction.
 */
export function bearingToDirection(bearing: number): string {
  const directions = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  const index = Math.round(bearing / 45) % 8;
  return directions[index];
}

/**
 * Format coordinates for display.
 */
export function formatCoordinates(lat: number, lon: number, precision = 4): string {
  return `${lat.toFixed(precision)}, ${lon.toFixed(precision)}`;
}

/**
 * Format speed for display.
 */
export function formatSpeed(speed: number): string {
  if (speed < 1) return '0 m/s';
  if (speed < 10) return `${speed.toFixed(1)} m/s`;
  return `${Math.round(speed)} m/s`;
}
"}

{"content": "/**
 * Custom hook for managing saved locations in cookies.
 * Provides persistence for user-defined named locations until
 * backend support is implemented.
 */
import { useState, useEffect, useCallback } from 'react';
import type { SavedLocation } from './types';

const COOKIE_NAME = 'ues_saved_locations';
const COOKIE_MAX_AGE = 365 * 24 * 60 * 60; // 1 year in seconds

/**
 * Parse saved locations from cookie string.
 */
function parseCookie(): SavedLocation[] {
  try {
    const cookies = document.cookie.split(';');
    for (const cookie of cookies) {
      const [name, value] = cookie.trim().split('=');
      if (name === COOKIE_NAME && value) {
        return JSON.parse(decodeURIComponent(value));
      }
    }
  } catch (error) {
    console.warn('Failed to parse saved locations cookie:', error);
  }
  return [];
}

/**
 * Save locations to cookie.
 */
function saveToCookie(locations: SavedLocation[]): void {
  const value = encodeURIComponent(JSON.stringify(locations));
  document.cookie = `${COOKIE_NAME}=${value}; max-age=${COOKIE_MAX_AGE}; path=/; SameSite=Lax`;
}

/**
 * Generate a unique ID for a saved location.
 */
function generateId(): string {
  return `loc_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
}

/**
 * Hook for managing saved/named locations with cookie persistence.
 * 
 * @returns Object with saved locations array and CRUD operations.
 */
export function useSavedLocations() {
  const [savedLocations, setSavedLocations] = useState<SavedLocation[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  // Load from cookie on mount
  useEffect(() => {
    const locations = parseCookie();
    setSavedLocations(locations);
    setIsLoaded(true);
  }, []);

  // Save a new location
  const saveLocation = useCallback((
    name: string,
    latitude: number,
    longitude: number,
    address?: string,
    altitude?: number
  ): SavedLocation => {
    const newLocation: SavedLocation = {
      id: generateId(),
      name,
      latitude,
      longitude,
      address,
      altitude,
    };

    setSavedLocations((prev) => {
      const updated = [...prev, newLocation];
      saveToCookie(updated);
      return updated;
    });

    return newLocation;
  }, []);

  // Update an existing location
  const updateLocation = useCallback((id: string, updates: Partial<Omit<SavedLocation, 'id'>>): void => {
    setSavedLocations((prev) => {
      const updated = prev.map((loc) =>
        loc.id === id ? { ...loc, ...updates } : loc
      );
      saveToCookie(updated);
      return updated;
    });
  }, []);

  // Delete a location
  const deleteLocation = useCallback((id: string): void => {
    setSavedLocations((prev) => {
      const updated = prev.filter((loc) => loc.id !== id);
      saveToCookie(updated);
      return updated;
    });
  }, []);

  // Find a location by name (case-insensitive)
  const findByName = useCallback((name: string): SavedLocation | undefined => {
    return savedLocations.find(
      (loc) => loc.name.toLowerCase() === name.toLowerCase()
    );
  }, [savedLocations]);

  // Check if a name already exists
  const nameExists = useCallback((name: string, excludeId?: string): boolean => {
    return savedLocations.some(
      (loc) => loc.name.toLowerCase() === name.toLowerCase() && loc.id !== excludeId
    );
  }, [savedLocations]);

  return {
    savedLocations,
    isLoaded,
    saveLocation,
    updateLocation,
    deleteLocation,
    findByName,
    nameExists,
  };
}
